html:
{%- set c = get_transport_order_context(doc) -%}
{%- set h = c.company -%}
{%- macro row(en, ar, value) -%}<tr><td class="lbl">{{ en }}</td><td><b>{{ value or "-" }}</b></td><td class="lbl-ar">{{ ar }}</td></tr>{%- endmacro -%}
{%- macro blank(en, ar) -%}<tr><td class="lbl">{{ en }}</td><td class="fill"></td><td class="lbl-ar">{{ ar }}</td></tr>{%- endmacro -%}
<style>
.bl { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #1d1d1d; }
.bl table { width: 100%; border-collapse: collapse; }
.bl .ar { direction: rtl; text-align: right; font-family: "Noto Naskh Arabic", "Noto Sans Arabic", Tahoma, "DejaVu Sans", Arial, sans-serif; }
.bl .hdr td { vertical-align: top; padding-bottom: 8px; border-bottom: 3px solid #0b3d6e; }
.bl .hdr-en, .bl .hdr-ar { width: 40%; line-height: 1.45; }
.bl .hdr-logo { width: 20%; text-align: center; vertical-align: middle !important; }
.bl .hdr-logo img { max-height: 70px; max-width: 150px; }
.bl .logo-ph { display: inline-block; width: 110px; height: 60px; line-height: 60px; border: 1px dashed #999; color: #999; font-size: 13px; letter-spacing: 2px; }
.bl .co-name { font-size: 15px; font-weight: bold; color: #0b3d6e; margin-bottom: 3px; }
.bl .title { margin: 10px 0; }
.bl .title td { background: #0b3d6e; color: #fff; padding: 6px 10px; font-size: 15px; font-weight: bold; }
.bl .box { border: 1px solid #c8c8c8; }
.bl .box th { background: #eef2f7; color: #0b3d6e; text-align: left; padding: 4px 6px; font-size: 11px; border-bottom: 1px solid #c8c8c8; }
.bl .box td { padding: 4px 6px; vertical-align: top; border-bottom: 1px solid #eee; }
.bl .lbl { color: #555; white-space: nowrap; width: 1%; }
.bl .lbl-ar { color: #555; white-space: nowrap; width: 1%; direction: rtl; text-align: right; font-family: "Noto Naskh Arabic", "Noto Sans Arabic", Tahoma, "DejaVu Sans", Arial, sans-serif; }
.bl .lines th { background: #eef2f7; color: #0b3d6e; border: 1px solid #c8c8c8; padding: 4px; font-size: 10px; text-align: center; }
.bl .lines td { border: 1px solid #ddd; padding: 4px; vertical-align: top; }
.bl .num { text-align: right; white-space: nowrap; }
.bl .ctr { text-align: center; }
.bl .muted { color: #777; font-size: 10px; }
.bl .gap { height: 10px; }
.bl .box th .bh { border: 0; padding: 4px 6px; font-weight: bold; color: #0b3d6e; white-space: nowrap; }
.bl .fill { border-bottom: 1px solid #888 !important; height: 22px; }
.bl .sign td { border: 1px solid #c8c8c8; vertical-align: top; padding: 6px; height: 95px; }
.bl .sign .cap { font-weight: bold; color: #0b3d6e; }
.bl .decl td { padding: 6px; background: #f7f9fb; border: 1px solid #e1e6ec; }
</style>
<div class="bl">
{#- The company Letter Head (logo, names, CR, VAT); the built header only when there is none. -#}
{%- if letter_head and not no_letterhead %}<div class="lh-top" style="margin-bottom:8px;">{{ letter_head }}</div>
{%- else %}
<table class="hdr"><tr>
	<td class="hdr-en">
		<div class="co-name">{{ h.name }}</div>
		{%- for line in h.address %}<div>{{ line }}</div>{% endfor %}
		{%- if h.tax_id %}<div>VAT No.: <b>{{ h.tax_id }}</b></div>{% endif %}
		{%- if h.cr %}<div>C.R. No.: <b>{{ h.cr }}</b></div>{% endif %}
	</td>
	<td class="hdr-logo">
		{%- if h.logo %}<img src="{{ h.logo }}">{% else %}<div class="logo-ph">LOGO</div>{% endif %}
	</td>
	<td class="hdr-ar ar">
		<div class="co-name">{% if h.name_ar %}{{ h.name_ar }}{% else %}<span dir="ltr">{{ h.name }}</span>{% endif %}</div>
		{%- for line in h.address_ar %}<div>{{ line }}</div>{% endfor %}
		{%- if h.tax_id %}<div>الرقم الضريبي: <b>{{ h.tax_id }}</b></div>{% endif %}
		{%- if h.cr %}<div>السجل التجاري: <b>{{ h.cr }}</b></div>{% endif %}
	</td>
</tr></table>
{%- endif %}

<table class="title"><tr>
	<td>TRANSPORT ORDER &nbsp;<span style="font-weight:normal;font-size:12px;color:#fff;">{{ c.order_no }}</span></td>
	<td class="ar">أمر نقل</td>
</tr></table>

<table><tr>
<td style="width:49%;vertical-align:top;">
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Shipment</td><td class="bh ar">الشحنة</td></tr></table></th></tr>
		{{ row("Job No.", "رقم العملية", c.job_no) }}
		{{ row("BL / AWB No.", "رقم البوليصة", c.bl_awb) }}
		{%- if c.carrier %}{{ row("Vessel / Flight", "السفينة / الرحلة", c.carrier) }}{% endif %}
		{%- if c.port %}{{ row("Port of Discharge", "ميناء التفريغ", c.port) }}{% endif %}
		{{ row("Customer", "العميل", c.customer) }}
		{%- if c.consignee %}{{ row("Consignee", "المرسل إليه", c.consignee) }}{% endif %}
	</table>
</td>
<td style="width:2%;"></td>
<td style="width:49%;vertical-align:top;">
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Truck and Driver</td><td class="bh ar">الشاحنة والسائق</td></tr></table></th></tr>
		{%- if c.transporter %}{{ row("Transporter", "الناقل", c.transporter) }}{% endif %}
		{{ row("Truck", "الشاحنة", c.vehicle) }}
		{{ row("Driver", "السائق", c.driver) }}
		{{ row("Driver Mobile", "جوال السائق", c.driver_mobile) }}
		{{ row("Status", "الحالة", c.status) }}
	</table>
</td>
</tr></table>
<div class="gap"></div>

<table><tr>
<td style="width:49%;vertical-align:top;">
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Pick up from</td><td class="bh ar">مكان الاستلام</td></tr></table></th></tr>
		{{ row("Place", "المكان", c.from_place) }}
		<tr><td class="lbl">Address</td><td><b>{{ c.from_address | join(", ") or "-" }}</b></td><td class="lbl-ar">العنوان</td></tr>
		{{ row("Pickup Date", "تاريخ الاستلام", c.pickup_date) }}
	</table>
</td>
<td style="width:2%;"></td>
<td style="width:49%;vertical-align:top;">
	<table class="box">
		<tr><th colspan="3" style="padding:0;"><table><tr><td class="bh">Deliver to</td><td class="bh ar">مكان التسليم</td></tr></table></th></tr>
		{{ row("Place", "المكان", c.to_place) }}
		<tr><td class="lbl">Address</td><td><b>{{ c.to_address | join(", ") or "-" }}</b></td><td class="lbl-ar">العنوان</td></tr>
		{{ row("Delivery Date", "تاريخ التسليم", c.delivery_date) }}
		{%- if c.delivery_time %}{{ row("Delivery Time", "وقت التسليم", c.delivery_time) }}{% endif %}
	</table>
</td>
</tr></table>
<div class="gap"></div>

<table class="lines">
	<thead><tr>
		<th style="width:5%;">#</th>
		<th style="width:20%;">Container No.<br><span class="ar">رقم الحاوية</span></th>
		<th style="width:14%;">Size / Type<br><span class="ar">الحجم / النوع</span></th>
		<th style="width:14%;">Seal No.<br><span class="ar">رقم الختم</span></th>
		<th style="width:10%;">Packages<br><span class="ar">عدد الطرود</span></th>
		<th style="width:12%;">Weight ({{ c.weight_uom }})<br><span class="ar">الوزن</span></th>
		<th>Description<br><span class="ar">الوصف</span></th>
	</tr></thead>
	<tbody>
	{%- for line in c.lines %}
	<tr>
		<td class="ctr">{{ line.idx }}</td>
		<td>{{ line.ref }}</td>
		<td>{{ line.kind }}</td>
		<td>{{ line.seal }}</td>
		<td class="num">{{ line.packages }}</td>
		<td class="num">{{ line.weight }}</td>
		<td>{{ line.description }}</td>
	</tr>
	{%- else %}
	<tr>
		<td class="ctr">1</td>
		<td colspan="4">{{ c.cargo or "-" }}</td>
		<td class="num">{{ c.gross_weight }}</td>
		<td></td>
	</tr>
	{%- endfor %}
	</tbody>
</table>
<div class="gap"></div>

<table class="sign"><tr>
	<td style="width:33%;"><div class="cap">Issued by</div><div class="ar">صادر من</div></td>
	<td style="width:34%;"><div class="cap">Driver's Signature</div><div class="ar">توقيع السائق</div></td>
	<td style="width:33%;"><div class="cap">Received by</div><div class="ar">المستلم</div></td>
</tr></table>
<div class="gap"></div>
<table><tr>
	<td class="muted">Printed {{ c.printed_on }} · {{ h.name }}</td>
	<td class="muted ar">{{ h.name_ar }}</td>
</tr></table>
</div>

{#- Letter Head footer (address, website, email): repeated at the foot of each PDF page. -#}
{%- if footer and not no_letterhead %}
<style>.print-format { margin-bottom: 22mm; }</style>
<div id="footer-html" class="visible-pdf">{{ footer }}</div>
{%- endif %}
